#root .vdet .vbar i{ background:var(--tx-2); }
/* v28.xx (cw-undercroft3), UI STEP 7 (his bar: "style consistency across menus"; critic on 06 and 07, both 2 of 5): the card windows
   (the Terms, the party, Wirt, the Last Pour) read as a header bar and a body, not a centred poster. The title sits LEFT at 32px over
   its hairline (style guide: header H), the card text rises to the 16px floor, the status lines go tx-1 (amber is for focus and the
   one action), the footer rule lines up with the card text instead of sticking out 28px each side, and HOST A PARTY is the one
   amber action of the party card. Looks only: no words, controls or order change. */
#root .modal > h3{ justify-content:flex-start; width:100%; box-sizing:border-box; font-size:32px; }
#root #termsmodal .msub, #root #partymodal .msub{ font-size:16px; line-height:1.5; }
#root #partymodal .hint, #root #partymodal textarea{ font-size:16px; line-height:1.5; }
#root #partymodal .hint{ color:var(--tx-2); }
#root #partystat, #root #partylen, #root #termstotal{ color:var(--tx-1) !important; font-weight:400 !important; font-size:16px !important; }
#root #termsmodal > .ui-foot, #root #gamblemodal > .ui-foot, #root #barmodal > .ui-foot, #root #partymodal > .ui-foot{ max-width:100%; box-sizing:border-box; }
#root #partyhost{ min-height:56px; background:var(--acc); color:var(--acc-ink); border-color:var(--acc); font-size:20px; letter-spacing:.06em; }
#root #partyhost:hover:not(:disabled){ background:#f7c25a; }

check:
{v:'VER',what:'the card windows have a left 32px title, the party status line is not amber, and HOST A PARTY is the amber action',
 run:function(){
   var bad=[];
   try{
     var m=document.getElementById('termsmodal'), h=m&&m.querySelector('h3');
     if(!h) bad.push('no terms title'); else { var cs=getComputedStyle(h);
       if(cs.justifyContent!=='flex-start'&&cs.justifyContent!=='start'&&cs.justifyContent!=='normal') bad.push('title is not left: '+cs.justifyContent);
       if(parseFloat(cs.fontSize)<31) bad.push('title is '+cs.fontSize+', not 32'); }
     var ps=document.getElementById('partystat');
     if(!ps) bad.push('no party status'); else { var c=getComputedStyle(ps).color; if(/rgb\(24[0-9],\s*18[0-9],\s*59\)/.test(c)) bad.push('party status is amber '+c); }
     var hb=document.getElementById('partyhost');
     if(!hb) bad.push('no host button'); else { var bg=getComputedStyle(hb).backgroundColor; if(!/rgb\(24[0-9],\s*18[0-9],\s*59\)/.test(bg)) bad.push('host button is not amber '+bg); }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   return bad.length?bad.join('; '):null; }},
